import {moneyMinor,allocations,balances} from './money.js';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cfg=window.POI_CONFIG;
async function timedFetch(input,init={}){const controller=new AbortController(),abort=()=>controller.abort(),timeout=setTimeout(abort,45000);if(init.signal?.aborted)abort();else init.signal?.addEventListener('abort',abort,{once:true});try{return await fetch(input,{...init,signal:controller.signal});}finally{clearTimeout(timeout);init.signal?.removeEventListener('abort',abort);}}
const db=window.supabase.createClient(cfg.url,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true},global:{fetch:timedFetch}});
const state={user:null,tab:'trips',eventId:'',events:[],attendance:[],moments:[],likes:[],comments:[],groups:[],members:[],expenses:[],payments:[],shares:[],settlements:[],directory:[],friends:[],feedback:[]};
let signup=false, busy=false, refreshing=false, refreshAgain=false, accountGeneration=0, channel=null, timer=null, lastSyncError=false, timingRetries=0;
const signedImages=new Map();
const viewedPhotos=new Set();
const event=()=>state.events.find(e=>e.id===state.eventId), group=()=>state.groups.find(g=>g.event_id===state.eventId);
const activeMembers=()=>state.members.filter(m=>m.group_id===group()?.id&&m.status==='active');
const name=()=>state.user?.user_metadata?.display_name||state.user?.user_metadata?.full_name||state.user?.email?.split('@')[0]||'Poi member';
const money=(n,c='INR')=>new Intl.NumberFormat('en-IN',{style:'currency',currency:c}).format(Number(n)/100);
const stamp=v=>new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
const notice=(message='')=>{$('notice').textContent=message;if($('dialog-error'))$('dialog-error').textContent=$('dialog').open?message:'';};
const empty=message=>`<div class="card empty">${esc(message)}</div>`;
function friendly(error){const m=error?.message||String(error);if(/jwt issued at future/i.test(m))return 'Your new session is not ready yet. Wait a moment and tap Refresh.';if(/invalid login credentials/i.test(m))return 'Email or password is incorrect. If you used Google previously, that is a separate sign-in method.';if(/fetch|network|offline|timeout/i.test(m))return 'Cannot reach Poi. Check your internet and retry. Nothing has been marked as saved.';if(/rate limit|too many/i.test(m))return 'Too many attempts. Wait a few minutes and retry.';if(/row-level|permission denied/i.test(m))return 'This account does not have access. Accept the invitation or check in before posting.';return m.slice(0,240);}
async function checked(request){const {data,error}=await request;if(error)throw error;return data;}
async function operation(fn){if(busy)return;busy=true;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);notice('Please wait…');try{const result=await fn();if(result!==false)notice(typeof result==='string'?result:'Saved to Poi.');}catch(e){notice(friendly(e));}finally{busy=false;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false);}}
function authUI(){ $('auth').hidden=!!state.user;$('workspace').hidden=!state.user;$('identity').innerHTML=state.user?`${esc(name())} <button class="quiet" data-action="signout">Sign out</button>`:'<span class="muted">For Android & iPhone</span>';if(state.user)return;
 $('auth').innerHTML=`<form id="auth-form" class="card auth-card"><h2>${signup?'Create your Poi account':'Welcome back'}</h2><p class="muted">Use the same account as the Android app. Gmail addresses work with email/password.</p>${signup?'<label>Your name<input name="name" autocomplete="name" required maxlength="60"></label>':''}<label>Email address<input name="email" type="email" autocomplete="email" required maxlength="120"></label><label>Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required ${signup?'minlength="8"':''}></label><label class="check"><input id="show-password" type="checkbox">Show password</label><button type="submit">${signup?'Create account':'Sign in'}</button><button type="button" class="quiet wide" data-action="auth-toggle">${signup?'Already have an account? Sign in':'New to Poi? Create account'}</button><button type="button" id="google-login" class="quiet wide" data-action="google" hidden>Continue with Google</button><p class="muted">Phone OTP is not enabled for this beta. No payment or SMS subscription is needed.</p></form>`;
 fetch(`${cfg.url}/auth/v1/settings`,{headers:{apikey:cfg.publishableKey}}).then(r=>r.json()).then(s=>{if($('google-login'))$('google-login').hidden=!s.external?.google;}).catch(()=>{});
}
async function refresh(){if(!state.user)return;if(refreshing){refreshAgain=true;return;}refreshing=true;const generation=accountGeneration;$('sync').textContent='Syncing…';try{
 const names=['events','attendance','event_moments','moment_likes','moment_comments','event_expense_groups','event_expense_members','event_expenses','event_expense_payments','event_expense_shares','event_expense_settlements','public_profile_directory','friendships','tester_feedback'];
 const values=await Promise.all(names.map(t=>checked(db.from(t).select('*').limit(1000))));if(generation!==accountGeneration)return;
 ['events','attendance','moments','likes','comments','groups','members','expenses','payments','shares','settlements','directory','friends','feedback'].forEach((key,i)=>state[key]=values[i]);
 state.events.sort((a,b)=>a.starts_at_millis-b.starts_at_millis);if(!state.events.some(e=>e.id===state.eventId))state.eventId=state.events[0]?.id||'';
 $('event').innerHTML=state.events.map(e=>`<option value="${esc(e.id)}" ${e.id===state.eventId?'selected':''}>${esc(e.title)}${e.visibility!=='public'?' · private':''}</option>`).join('')||'<option>No events yet — create your trip below</option>';
 $('sync').textContent=`Database updated ${new Date().toLocaleTimeString()}`;
 if(lastSyncError){notice();lastSyncError=false;}timingRetries=0;
 // Never replace a form while the user is writing feedback or a trip description.
 if(!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||!$('content').contains(document.activeElement))render();
 }catch(e){$('sync').textContent='Not synced · retry with Refresh';lastSyncError=true;notice(friendly(e));if(/jwt issued at future/i.test(e.message||'')&&timingRetries++<2)setTimeout(()=>{if(generation===accountGeneration)refresh();},1500);}finally{refreshing=false;if(refreshAgain){refreshAgain=false;refresh();}}}
function subscribe(){if(channel){db.removeChannel(channel);channel=null;}if(!state.user)return;
 channel=db.channel(`trip-${state.user.id}`).on('postgres_changes',{event:'*',schema:'public'},()=>{clearTimeout(timer);timer=setTimeout(refresh,600);}).subscribe(status=>{if(status==='CHANNEL_ERROR'||status==='TIMED_OUT')$('sync').textContent='Live connection interrupted · use Refresh';});
}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.tab===state.tab));
 const e=event();if(state.tab==='trips')renderTrips();else if(state.tab==='people')renderPeople();else if(state.tab==='feedback')renderFeedback();else if(!e)$('content').innerHTML=empty('Create or select an event first.');else if(state.tab==='photos')renderPhotos(e);else renderExpenses(e);}
function renderTrips(){const e=event(),attendance=state.attendance.find(a=>a.event_id===e?.id&&a.user_id===state.user.id);
 $('content').innerHTML=`${e?`<article class="card"><span class="badge">${esc(e.visibility==='public'?'Public event':'Private trip')}</span><h2>${esc(e.title)}</h2><p>${esc(e.summary)}</p><p><strong>${esc(e.venue)}</strong><br>${esc(e.address)}<br>${stamp(e.starts_at_millis)} → ${stamp(e.ends_at_millis)}</p>${e.is_cancelled?'<p class="error">This event was cancelled.</p>':`<p class="muted">Your status: ${esc(attendance?.status||'Not selected')}</p><div class="row">${['interested','going','here'].map(s=>`<button class="${attendance?.status===s?'':'quiet'}" data-action="attendance" data-status="${s}">${s==='here'?"I'm here · self check-in":s==='going'?"I'm going":'Interested'}</button>`).join('')}</div><p class="muted">Self check-in is not GPS-verified. Use it only when you actually attend.</p>`}</article>`:empty('Create your Goa or Munnar trip with your real dates. No sample trips are published automatically.')}
 <details class="card"><summary><strong>Create an event / trip</strong></summary><form id="event-form"><label>Event name<input name="title" required maxlength="80" placeholder="For example: Our Goa ride"></label><label>About this trip<textarea name="summary" required maxlength="300"></textarea></label><div class="grid"><label>Starts<input name="start" type="datetime-local" required></label><label>Ends<input name="end" type="datetime-local" required></label></div><label>Venue<input name="venue" required maxlength="120"></label><label>Address / area<input name="address" required maxlength="240"></label><label>Visibility<select name="visibility"><option value="circle">Private · accepted friends</option><option value="invite_only">Private · invited friends only</option><option value="public">Public · anyone can view</option></select></label><p class="muted">For invite-only trips, use event invitations in the Android app. For private circle trips, connect as friends in People.</p><button class="wide" type="submit">Create trip</button></form></details>`;}
async function signedImage(path,bucket='event-moments'){const key=bucket+path,cache=signedImages.get(key);if(cache&&cache.until>Date.now())return cache.url;const d=await checked(db.storage.from(bucket).createSignedUrl(path,3600));signedImages.set(key,{url:d.signedUrl,until:Date.now()+3000000});return d.signedUrl;}
function renderPhotos(e){const list=state.moments.filter(m=>m.event_id===e.id).sort((a,b)=>b.created_at_millis-a.created_at_millis),attendance=state.attendance.find(a=>a.event_id===e.id&&a.user_id===state.user.id),allowed=['here','attended'].includes(attendance?.status);
 $('content').innerHTML=`<h2>Moments from ${esc(e.title)}</h2><p class="muted">Likes, comments and photos are shared with people allowed to view this event.</p>${allowed?`<form id="photo-form" class="card"><label>Choose photo<input name="image" type="file" accept="image/*" required></label><label>Caption<textarea name="caption" maxlength="500" placeholder="A moment worth keeping…"></textarea></label><p class="muted">Photos are resized to reduce mobile data. Private signed image links expire in an hour.</p><button type="submit">Upload photo</button></form>`:empty("Mark “I'm here” when you attend, then return here to upload photos.")}
 ${list.map(m=>`<article class="card photo-card"><p><strong>${esc(m.author_name)}</strong> <small>${stamp(m.created_at_millis)}</small></p><img class="photo" id="image-${m.id}" alt="${esc(m.caption||'Event photo')}" loading="lazy"><p>${esc(m.caption)}</p><div class="stats"><button class="quiet" data-action="like" data-id="${m.id}">${state.likes.some(l=>l.moment_id===m.id)?'♥':'♡'} ${m.like_count}</button><span class="muted">${m.comment_count} comments · ${m.view_count} views</span><button class="quiet" data-action="share" data-id="${m.id}">Share</button>${m.author_id===state.user.id?`<button class="quiet" data-action="delete-photo" data-id="${m.id}">Delete</button>`:''}</div><div>${state.comments.filter(c=>c.moment_id===m.id).sort((a,b)=>a.created_at_millis-b.created_at_millis).slice(-6).map(c=>`<p class="muted"><strong>${esc(c.author_name)}</strong> ${esc(c.body)}</p>`).join('')}</div><form class="comment-form row" data-id="${m.id}"><input name="body" maxlength="500" required placeholder="Add a comment" aria-label="Comment on photo"><button type="submit">Send</button></form></article>`).join('')||empty('Be the first to share a trip moment.')}`;
 list.forEach(async m=>{try{const url=await signedImage(m.image_path);const img=$(`image-${m.id}`);if(img){img.onload=()=>{if(!viewedPhotos.has(m.id)){viewedPhotos.add(m.id);db.from('moment_views').insert({moment_id:m.id,user_id:state.user.id}).then(({error})=>{if(error&&error.code!=='23505')viewedPhotos.delete(m.id);});}};img.src=url;}}catch{const img=$(`image-${m.id}`);if(img)img.alt='Photo unavailable. Refresh to retry.';}});}
function renderPeople(){const incoming=state.friends.filter(f=>f.addressee_id===state.user.id&&f.status==='pending');
 $('content').innerHTML=`<h2>Your people</h2><p class="muted">Connect as friends first. Then invite them into your private circle trip or expense group.</p><label>Find by name or handle<input id="people-search" placeholder="Type at least 2 characters" autocomplete="off"></label><div id="people-results"></div><h3>Friend requests</h3>${incoming.map(f=>`<div class="card row"><span>${esc(state.directory.find(p=>p.id===f.requester_id)?.display_name||'Poi member')}</span><button data-action="accept-friend" data-id="${f.id}">Accept</button></div>`).join('')||empty('No new friend requests.')}<h3>Accepted friends</h3>${friendProfiles().map(p=>`<div class="card"><strong>${esc(p.display_name)}</strong><p class="muted">@${esc(p.handle||'member')} · ${esc(p.home_area||'')}</p></div>`).join('')||empty('Find your friends above and accept the request on their account.')}`;}
function friendProfiles(){return state.directory.filter(p=>p.id!==state.user.id&&state.friends.some(f=>f.status==='accepted'&&[f.requester_id,f.addressee_id].includes(p.id)));}
function renderFeedback(){ $('content').innerHTML=`<h2>Make Poi better, together.</h2><form id="feedback-form" class="card"><p class="muted">Tell us what happened, what you expected, and how to repeat it. Never include passwords or banking details.</p><label>Feature<select name="category">${['login','photos','expenses','events','other'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Your experience<select name="rating"><option value="5">5 · Great</option><option value="4">4 · Good</option><option value="3">3 · Okay</option><option value="2">2 · Difficult</option><option value="1">1 · Could not use it</option></select></label><label>Feedback<textarea name="message" minlength="10" maxlength="2000" required></textarea></label><button type="submit">Send feedback</button></form><h3>Your submitted feedback</h3>${state.feedback.filter(f=>f.user_id===state.user.id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).map(f=>`<div class="card"><span class="badge">${esc(f.category)} · ${f.rating}/5</span><p>${esc(f.message)}</p><small>${stamp(f.created_at)} · ${esc(f.platform)}</small></div>`).join('')||empty('Your feedback will appear here after it is saved to the database.')}`;}
function renderExpenses(e){const g=group();if(!g){$('content').innerHTML=`<h2>Split the trip, not the friendship.</h2><p class="muted">Expenses stay private to accepted group members—even for a public event.</p><button data-action="start-group">Start expense group for ${esc(e.title)}</button>`;return;}
 const me=state.members.find(m=>m.group_id===g.id&&m.user_id===state.user.id);if(me?.status==='invited'){$('content').innerHTML=`<div class="card"><h2>You're invited to the expense group</h2><p>${esc(e.title)}</p><button data-action="accept-group">Join group</button></div>`;return;}
 if(me?.status!=='active'){$('content').innerHTML=empty('Only active group members can use these expenses.');return;}
 const members=activeMembers(),expenses=state.expenses.filter(x=>x.group_id===g.id&&!x.deleted_at_millis),ids=new Set(expenses.map(x=>x.id)),settlements=state.settlements.filter(s=>s.group_id===g.id),balance=balances(members,state.payments.filter(p=>ids.has(p.expense_id)),state.shares.filter(p=>ids.has(p.expense_id)),settlements);
 $('content').innerHTML=`<h2>${esc(e.title)} · expenses</h2><div class="card"><span class="muted">Trip total · ${esc(g.currency)}</span><div class="money">${money(expenses.reduce((a,b)=>a+Number(b.amount_minor),0),g.currency)}</div><p class="muted">Positive balance = should receive. Negative = owes. Pending settlements do not change balances.</p>${members.map(m=>`<div class="splitrow"><span>${esc(m.display_name)}${m.user_id===state.user.id?' · you':''}</span><strong class="${balance[m.user_id]>=0?'positive':'error'}">${money(balance[m.user_id],g.currency)}</strong></div>`).join('')}<div class="row" style="margin-top:16px"><button data-action="expense-new">Add expense</button><button class="quiet" data-action="settle-new">Record payment</button><button class="quiet" data-action="export">Export CSV</button></div></div>
 ${g.created_by===state.user.id?`<details class="card"><summary>Invite an accepted friend</summary><form id="member-form"><label>Friend<select name="user" required>${friendProfiles().filter(p=>!state.members.some(m=>m.group_id===g.id&&m.user_id===p.id)).map(p=>`<option value="${p.id}">${esc(p.display_name)}</option>`).join('')}</select></label><button type="submit">Invite to expenses</button></form><p class="muted">They must accept this invitation before being included in any split.</p></details>`:''}
 <h3>Expenses</h3>${expenses.sort((a,b)=>b.created_at_millis-a.created_at_millis).map(x=>`<article class="card"><span class="badge">${esc(x.category)} · ${esc(x.split_method)}</span><h3>${esc(x.title)} · ${money(x.amount_minor,g.currency)}</h3><p>${esc(x.note)}</p><small>Added by ${esc(x.created_by_name)}</small><div class="row" style="margin-top:12px">${x.receipt_path?`<button class="quiet" data-action="receipt" data-id="${x.id}">Receipt</button>`:''}${x.created_by===state.user.id||g.created_by===state.user.id?`<button class="quiet" data-action="expense-edit" data-id="${x.id}">Edit</button><button class="quiet" data-action="expense-delete" data-id="${x.id}">Delete</button>`:''}</div></article>`).join('')||empty('Add fuel, food, hotel or ticket expenses as you go.')}<h3>Recorded payments</h3>${settlements.map(s=>`<div class="card"><strong>${esc(s.payer_name)} → ${esc(s.payee_name)} · ${money(s.amount_minor,g.currency)}</strong><p>${esc(s.note)} · ${esc(s.status)}</p>${s.status==='pending'&&s.payee_id===state.user.id?`<button data-action="settle-confirm" data-id="${s.id}">Confirm money received</button>`:''}</div>`).join('')||empty('Record payments made outside Poi. Poi does not move money.')}`;}
function expenseDialog(id){const x=state.expenses.find(x=>x.id===id),members=activeMembers(),g=group(),payers=state.payments.filter(p=>p.expense_id===id);if(x&&payers.length>1){notice('Use Android to edit this multi-payer expense. The web companion will not overwrite its payer allocations.');return;} $('dialog-content').innerHTML=`<h2>${x?'Edit expense':'Add an expense'}</h2><form id="expense-form" data-id="${id||''}"><label>Title<input name="title" required maxlength="100" value="${esc(x?.title)}"></label><label>Amount (${esc(g.currency)})<input name="amount" required inputmode="decimal" value="${x?Number(x.amount_minor)/100:''}"></label><label>Category<select name="category">${['travel','food','stay','tickets','shopping','other'].map(c=>`<option ${x?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Paid by<select name="payer">${members.map(m=>`<option value="${m.user_id}" ${m.user_id===(x?payers[0]?.user_id:state.user.id)?'selected':''}>${esc(m.display_name)}</option>`).join('')}</select></label><label>Split method<select name="method" id="split-method">${['equal','exact','percentage','shares'].map(m=>`<option ${x?.split_method===m?'selected':''}>${m}</option>`).join('')}</select></label><p class="muted">For exact splits enter currency amounts; percentage totals must equal 100; shares use whole-number weights. When editing percentages or shares, re-enter the intended weights.</p>${members.map(m=>`<div class="splitrow"><label class="check"><input type="checkbox" name="participant" value="${m.user_id}" ${!x||state.shares.some(s=>s.expense_id===id&&s.user_id===m.user_id)?'checked':''}>${esc(m.display_name)}</label><input aria-label="Split value for ${esc(m.display_name)}" data-weight="${m.user_id}" inputmode="decimal" value="${x?.split_method==='exact'?Number(state.shares.find(s=>s.expense_id===id&&s.user_id===m.user_id)?.amount_minor||0)/100:x&&['percentage','shares'].includes(x.split_method)?'':'1'}"></div>`).join('')}<label>Note<textarea name="note" maxlength="500">${esc(x?.note)}</textarea></label>${x?'<p class="muted">Existing receipts are kept. Use Android for multi-payer expenses.</p>':'<label>Receipt (optional)<input name="receipt" type="file" accept="image/*"></label>'}<button class="wide" type="submit">Save expense</button></form>`;$('dialog').showModal();}
function settlementDialog(){const g=group();$('dialog-content').innerHTML=`<h2>Record a payment</h2><p>This is a record only. Pay outside Poi first; the recipient confirms receipt.</p><form id="settlement-form"><label>Paid to<select name="payee">${activeMembers().filter(m=>m.user_id!==state.user.id).map(m=>`<option value="${m.user_id}">${esc(m.display_name)}</option>`).join('')}</select></label><label>Amount (${esc(g.currency)})<input name="amount" inputmode="decimal" required></label><label>Note<textarea name="note" maxlength="300"></textarea></label><button class="wide" type="submit">Record pending payment</button></form>`;$('dialog').showModal();}
async function photoBlob(file){if(!file||!file.type.startsWith('image/'))throw Error('Choose a photo.');if(file.size>40*1024*1024)throw Error('Photo is too large. Choose one under 40 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(!img.naturalWidth||img.naturalWidth>40000||img.naturalHeight>40000)throw Error('Unsupported image size.');const scale=Math.min(1,2048/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob||blob.size>6*1024*1024)throw Error('Could not prepare photo. Try a smaller JPEG.');return blob;}finally{URL.revokeObjectURL(url);}}
document.addEventListener('change',e=>{if(e.target.id==='event'){state.eventId=e.target.value;render();}if(e.target.id==='show-password')document.querySelector('[name=password]').type=e.target.checked?'text':'password';});
document.addEventListener('input',e=>{if(e.target.id==='people-search'){const q=e.target.value.trim().toLowerCase();$('people-results').innerHTML=q.length<2?'':state.directory.filter(p=>p.id!==state.user.id&&`${p.display_name} ${p.handle}`.toLowerCase().includes(q)).slice(0,20).map(p=>`<div class="card row"><strong>${esc(p.display_name)}</strong><small>@${esc(p.handle)}</small>${state.friends.some(f=>[f.requester_id,f.addressee_id].includes(p.id))?'<span class="badge">Request sent / connected</span>':`<button data-action="friend" data-id="${p.id}">Add friend</button>`}</div>`).join('')||empty('No matching users. Ask your friend to create a Poi account first.');}});
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.tab){state.tab=b.dataset.tab;render();return;}const action=b.dataset.action,id=b.dataset.id;if(!action)return;
 if(action==='auth-toggle'){signup=!signup;authUI();notice();return;}if(action==='signout'){await db.auth.signOut();return;}if(action==='google'){notice('Opening Google sign-in…');try{await checked(db.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/'}}));}catch(e){notice(friendly(e));}return;}
 if(action==='expense-new'||action==='expense-edit'){expenseDialog(id);return;}if(action==='settle-new'){settlementDialog();return;}
 if(action==='export'){const g=group(),rows=state.expenses.filter(x=>x.group_id===g.id&&!x.deleted_at_millis);const csvCell=v=>'"'+String(v??'').replace(/^([=+@-])/,'\t$1').replace(/"/g,'""')+'"';const csv=['Title,Amount,Currency,Category,Split,Note',...rows.map(x=>[x.title,Number(x.amount_minor)/100,x.currency,x.category,x.split_method,x.note].map(csvCell).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='poi-trip-expenses.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 await operation(async()=>{const g=group();if(action==='attendance'){await checked(db.from('attendance').upsert({event_id:state.eventId,user_id:state.user.id,status:b.dataset.status,visibility:'private'},{onConflict:'event_id,user_id'}));}
 else if(action==='friend')await checked(db.from('friendships').insert({requester_id:state.user.id,addressee_id:id}));
 else if(action==='accept-friend')await checked(db.from('friendships').update({status:'accepted'}).eq('id',id));
 else if(action==='start-group')await checked(db.from('event_expense_groups').insert({event_id:state.eventId,created_by:state.user.id,currency:'INR'}));
 else if(action==='accept-group')await checked(db.from('event_expense_members').update({status:'active'}).eq('group_id',g.id).eq('user_id',state.user.id));
 else if(action==='like'){if(state.likes.some(l=>l.moment_id===id))await checked(db.from('moment_likes').delete().eq('moment_id',id).eq('user_id',state.user.id));else await checked(db.from('moment_likes').insert({moment_id:id,user_id:state.user.id}));}
 else if(action==='share'){const m=state.moments.find(m=>m.id===id),url=await signedImage(m.image_path);if(navigator.share)await navigator.share({title:event().title,text:m.caption,url});else{await navigator.clipboard.writeText(url);return 'Private link copied. It expires in one hour.';}}
 else if(action==='delete-photo'){if(!confirm('Delete your photo from this event?'))return false;const m=state.moments.find(m=>m.id===id);await checked(db.from('event_moments').delete().eq('id',id));await checked(db.storage.from('event-moments').remove([m.image_path]));}
 else if(action==='expense-delete'){if(!confirm('Remove this expense? Its audit record is retained.'))return false;await checked(db.rpc('delete_poi_event_expense',{p_expense_id:id}));}
 else if(action==='settle-confirm'){if(!confirm('Confirm that you actually received this payment?'))return false;await checked(db.from('event_expense_settlements').update({status:'confirmed'}).eq('id',id));}
 else if(action==='receipt'){const x=state.expenses.find(x=>x.id===id),url=await signedImage(x.receipt_path,'event-expense-receipts');$('dialog-content').innerHTML=`<h2>Receipt</h2><img class="photo" src="${esc(url)}" alt="Private expense receipt">`;$('dialog').showModal();return;}
 document.activeElement?.blur();await refresh();render();});});
document.addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target,f=new FormData(form);operation(async()=>{
 if(form.id==='auth-form'){const email=String(f.get('email')).trim().toLowerCase(),password=String(f.get('password'));if(signup){if(password.length<8||!/[A-Za-z]/.test(password)||!/[0-9]/.test(password))throw Error('Use at least 8 characters with letters and numbers.');const data=await checked(db.auth.signUp({email,password,options:{data:{display_name:String(f.get('name')).trim()}}}));if(!data.session)return 'Check your email to confirm the account, then sign in.';}else await checked(db.auth.signInWithPassword({email,password}));return 'Signed in to Poi.';}
 if(form.id==='event-form'){const start=new Date(f.get('start')).getTime(),end=new Date(f.get('end')).getTime();if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)throw Error('End date/time must be after the start.');const data=await checked(db.from('events').insert({title:String(f.get('title')).trim(),summary:String(f.get('summary')).trim(),description:String(f.get('summary')).trim(),category:'community',starts_at_millis:start,ends_at_millis:end,venue:String(f.get('venue')).trim(),address:String(f.get('address')).trim(),organizer_name:name(),created_by:state.user.id,visibility:f.get('visibility'),theme_key:'community',check_in_radius_meters:500}).select().single());state.eventId=data.id;}
 else if(form.id==='photo-form'){const id=crypto.randomUUID(),path=`${state.eventId}/${state.user.id}/${id}.jpg`,blob=await photoBlob(f.get('image'));await checked(db.storage.from('event-moments').upload(path,blob,{contentType:'image/jpeg',upsert:false}));try{await checked(db.from('event_moments').insert({id,event_id:state.eventId,author_id:state.user.id,author_name:name(),image_path:path,caption:String(f.get('caption')).trim(),created_at_millis:Date.now()}));}catch(e){await db.storage.from('event-moments').remove([path]);throw e;}}
 else if(form.classList.contains('comment-form'))await checked(db.from('moment_comments').insert({moment_id:form.dataset.id,author_id:state.user.id,author_name:name(),body:String(f.get('body')).trim(),created_at_millis:Date.now()}));
 else if(form.id==='member-form')await checked(db.from('event_expense_members').insert({group_id:group().id,user_id:f.get('user'),invited_by:state.user.id}));
 else if(form.id==='feedback-form'){await checked(db.from('tester_feedback').insert({user_id:state.user.id,category:f.get('category'),rating:Number(f.get('rating')),message:String(f.get('message')).trim(),platform:'web',app_version:'trip-beta-1'}));form.reset();}
 else if(form.id==='expense-form'){const g=group(),total=moneyMinor(f.get('amount'));if(total<=0)throw Error('Amount must be greater than zero.');const rows=f.getAll('participant').map(id=>({id,value:form.querySelector(`[data-weight="${id}"]`).value})),shares=allocations(total,rows,f.get('method')),payments=[{user_id:f.get('payer'),amount_minor:total}],id=form.dataset.id||crypto.randomUUID();let receiptPath=null;const receipt=f.get('receipt');if(receipt?.size){receiptPath=`${g.id}/${state.user.id}/${id}.jpg`;await checked(db.storage.from('event-expense-receipts').upload(receiptPath,await photoBlob(receipt),{contentType:'image/jpeg',upsert:false}));}
 const params={p_expense_id:id,p_title:String(f.get('title')).trim(),p_note:String(f.get('note')).trim(),p_category:f.get('category'),p_amount_minor:total,p_split_method:f.get('method'),p_payments:payments,p_shares:shares};
 try{if(form.dataset.id)await checked(db.rpc('update_poi_event_expense',{...params,p_updated_at_millis:Date.now()}));else await checked(db.rpc('create_poi_event_expense',{...params,p_group_id:g.id,p_currency:g.currency,p_receipt_path:receiptPath,p_created_at_millis:Date.now()}));}catch(e){if(receiptPath)await db.storage.from('event-expense-receipts').remove([receiptPath]);throw e;}$('dialog').close();}
 else if(form.id==='settlement-form'){const amount=moneyMinor(f.get('amount'));if(amount<=0||!f.get('payee'))throw Error('Choose a recipient and positive amount.');await checked(db.from('event_expense_settlements').insert({group_id:group().id,payer_id:state.user.id,payee_id:f.get('payee'),amount_minor:amount,currency:group().currency,note:String(f.get('note')).trim()}));$('dialog').close();}
 document.activeElement?.blur();await refresh();render();});});
$('close-dialog').onclick=()=>$('dialog').close();$('refresh').onclick=()=>{document.activeElement?.blur();refresh();};
async function accountChanged(session){const user=session?.user||null;if(state.user?.id===user?.id)return;accountGeneration++;state.user=user;signedImages.clear();viewedPhotos.clear();for(const key of ['events','attendance','moments','likes','comments','groups','members','expenses','payments','shares','settlements','directory','friends','feedback'])state[key]=[];state.eventId='';$('dialog').close();$('content').innerHTML='';authUI();subscribe();if(user)await refresh();}
db.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>accountChanged(session),0);});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh();});window.addEventListener('online',refresh);window.addEventListener('offline',()=>{$('sync').textContent='Offline · reconnect before saving';notice('Offline. Your changes are not saved until a request succeeds.');});
authUI();const initial=await db.auth.getSession();if(initial.error)notice(friendly(initial.error));else await accountChanged(initial.data.session);
